/* 학습 해설
 * ext4 이름 해시의 바이트 부호: 같은 0x80이 다른 숫자가 되는 이유
 * 디렉터리 인덱스는 파일 이름의 해시를 저장하므로 계산 방식이 달라지면 같은 이름도 다른 검색 위치를 가리킬 수 있습니다. char의 부호 해석을 명시한 버전을 따로 두면 기존 디스크 형식의 계산을 재현할 수 있습니다.
 * legacy helper는 hash0=0x12a3fe2d, hash1=0x37abe8f9에서 시작합니다. 바이트마다 hash1+(hash0 XOR (문자값*7152373))을 계산하고 최상위 비트가 있으면 0x7fffffff를 뺍니다. hash1에는 이전 hash0를, hash0에는 새 값을 넣습니다. 마지막은 hash0<<1입니다. unsigned helper는 unsigned char, signed helper는 signed char를 int로 확장합니다. __u32 상태의 연산은 32비트 결과로 유지됩니다.
 * 0x41은 두 버전 모두 65입니다. 0x80은 unsigned에서 128, signed에서 -128이므로 같은 바이트라도 곱셈 입력이 다릅니다. 길이가 0이면 루프 없이 초기 hash0를 한 비트 옮긴 0x2547fc5a입니다. name은 NUL로 끝나는지 검색하지 않고 len회 읽으므로 호출자가 유효한 길이를 제공해야 합니다.
 */
static __u32 dx_hack_hash_unsigned(const char *name, int len)
{
	__u32 hash, hash0 = 0x12a3fe2d, hash1 = 0x37abe8f9;
	const unsigned char *ucp = (const unsigned char *) name;

	while (len--) {
		hash = hash1 + (hash0 ^ (((int) *ucp++) * 7152373));

		if (hash & 0x80000000)
			hash -= 0x7fffffff;
		hash1 = hash0;
		hash0 = hash;
	}
	return hash0 << 1;
}

static __u32 dx_hack_hash_signed(const char *name, int len)
{
	__u32 hash, hash0 = 0x12a3fe2d, hash1 = 0x37abe8f9;
	const signed char *scp = (const signed char *) name;

	while (len--) {
		hash = hash1 + (hash0 ^ (((int) *scp++) * 7152373));

		if (hash & 0x80000000)
			hash -= 0x7fffffff;

/* 학습 해설
 * ext4 해시 입력 묶기: 길이 패딩과 네 바이트 누적
 * 해시 변환은 정해진 개수의 32비트 숫자를 입력으로 받지만 파일 이름 길이는 제각각입니다. 문자열을 숫자로 묶고 남은 칸을 일정한 규칙으로 채워야 같은 이름을 항상 같은 방식으로 계산할 수 있습니다.
 * str2hashbuf는 원래 len으로 pad=len|(len<<8), 이어 pad|=pad<<16을 만듭니다. 그 뒤 이번 처리 길이를 num*4 이하로 줄입니다. val은 pad에서 시작해 매 바이트마다 문자값+(val<<8)로 갱신됩니다. 네 바이트마다 buf에 쓰고 val을 pad로 되돌리며 num을 줄입니다. 남은 칸이 있으면 부분 val을 쓰고 나머지는 pad로 채웁니다. signed 변형은 signed char를 사용한다는 점에서 다릅니다.
 * len=1, unsigned 문자 A=0x41이면 pad=0x01010101이고 첫 출력은 0x01010141입니다. num=4라면 나머지 세 칸은 pad입니다. len=20,num=4이면 pad는 원래 길이 20의 0x14141414이고 이번에는 16바이트만 읽습니다. 패딩을 자른 길이 16으로 만들지 않습니다.
 */
static void str2hashbuf_unsigned(const char *msg, int len, __u32 *buf, int num)
{
	__u32	pad, val;
	int	i;
	const unsigned char *ucp = (const unsigned char *) msg;

	pad = (__u32)len | ((__u32)len << 8);
	pad |= pad << 16;

	val = pad;
	if (len > num*4)
		len = num * 4;
	for (i = 0; i < len; i++) {
		val = ((int) ucp[i]) + (val << 8);
		if ((i % 4) == 3) {
			*buf++ = val;
			val = pad;
			num--;
		}
	}
	if (--num >= 0)
		*buf++ = val;
	while (--num >= 0)
		*buf++ = pad;
}

/* 학습 해설
 * ext4 TEA 변환: 새 b0를 다음 계산에 사용하는 16회 혼합
 * 파일 이름의 일부 바이트가 바뀌었을 때 검색용 숫자의 여러 비트가 달라지도록 덧셈·shift·XOR를 반복해 섞습니다. 원문 계산 순서를 바꾸면 같은 이름의 해시를 재현할 수 없습니다.
 * TEA_transform은 buf[0],buf[1]을 b0,b1에 복사하고 입력 네 word를 a,b,c,d에 둡니다. sum은 0, 반복 수는 16입니다. 매 회 sum에 0x9E3779B9를 더하고 b1의 좌우 shift·sum·a,b를 섞어 b0에 더합니다. 바로 이어 갱신된 b0와 c,d를 사용해 b1을 갱신합니다. 끝난 b0,b1은 기존 buf[0],buf[1]에 다시 더합니다. buf[2],buf[3]에는 이 함수가 쓰지 않습니다.
 * 첫 회 sum은 DELTA이며 두 번째 회는 32비트 범위에서 2*DELTA입니다. b0와 b1을 둘 다 이전 값만으로 동시에 계산하는 변형은 이 코드와 다릅니다. 호출부는 이름을 16바이트 단위로 묶어 같은 buf에 여러 번 변환하고 최종 buf[0]과 buf[1]을 major/minor 결과로 고릅니다.
 */
static void TEA_transform(__u32 buf[4], __u32 const in[])
{
	__u32	sum = 0;
	__u32	b0 = buf[0], b1 = buf[1];
	__u32	a = in[0], b = in[1], c = in[2], d = in[3];
	int	n = 16;

	do {
		sum += DELTA;
		b0 += ((b1 << 4)+a) ^ (b1+sum) ^ ((b1 >> 5)+b);
		b1 += ((b0 << 4)+c) ^ (b0+sum) ^ ((b0 >> 5)+d);
	} while (--n);

	buf[0] += b0;
	buf[1] += b1;
}

/* F, G and H are basic MD4 functions: selection, majority, parity */
#define F(x, y, z) ((z) ^ ((x) & ((y) ^ (z))))
#define G(x, y, z) (((x) & (y)) + (((x) ^ (y)) & (z)))
#define H(x, y, z) ((x) ^ (y) ^ (z))

/*
 * The generic round function.  The application is so specific that
 * we don't bother protecting all the arguments with parens, as is generally
 * good macro practice, in favor of extra legibility.
 * Rotation is separate from addition to prevent recomputation
 */

/* 학습 해설
 * ext4 half-MD4: 선택·다수결·XOR와 회전 연산
 * 입력 word를 여러 순서로 상태에 섞으면 이름의 위치별 차이가 결과에 반영됩니다. 이 코드의 핵심은 비트별 논리, 32비트 덧셈, 밀려난 비트를 반대편으로 되돌리는 회전을 조합하는 것입니다.
 * F=z XOR (x AND (y XOR z))는 x가 1인 비트에서 y, 0이면 z를 고릅니다. G=(x AND y)+((x XOR y) AND z)는 비트별 다수결입니다. 두 항이 같은 비트에서 함께 1일 수 없어 여기서는 덧셈이 OR와 같은 효과입니다. H=x XOR y XOR z는 parity입니다. ROUND는 a에 함수값과 입력을 더한 뒤 rol32(a,s)로 회전합니다. 세 라운드가 각각 8회이고 입력 순서와 회전 수는 원문에 고정돼 있습니다.
 * 한 비트 x=1,y=0,z=1이면 F=0,G=1,H=0입니다. 32비트 값 0x80000001을 왼쪽으로 1 회전하면 0x00000003이 됩니다. 단순 shift이면 맨 위 비트가 버려져 0x00000002입니다. 이 차이가 해시 결과를 바꿉니다. 상태 a,b,c,d는 각각 buf[0..3]에 누적하며 반환은 buf[1]입니다.
 */
static __u32 half_md4_transform(__u32 buf[4], __u32 const in[8])
{
	__u32 a = buf[0], b = buf[1], c = buf[2], d = buf[3];

	/* Round 1 */
	ROUND(F, a, b, c, d, in[0] + K1,  3);
	ROUND(F, d, a, b, c, in[1] + K1,  7);
	ROUND(F, c, d, a, b, in[2] + K1, 11);
	ROUND(F, b, c, d, a, in[3] + K1, 19);
	ROUND(F, a, b, c, d, in[4] + K1,  3);
	ROUND(F, d, a, b, c, in[5] + K1,  7);
	ROUND(F, c, d, a, b, in[6] + K1, 11);
	ROUND(F, b, c, d, a, in[7] + K1, 19);

	/* Round 2 */
	ROUND(G, a, b, c, d, in[1] + K2,  3);
	ROUND(G, d, a, b, c, in[3] + K2,  5);
	ROUND(G, c, d, a, b, in[5] + K2,  9);
	ROUND(G, b, c, d, a, in[7] + K2, 13);
	ROUND(G, a, b, c, d, in[0] + K2,  3);
	ROUND(G, d, a, b, c, in[2] + K2,  5);
	ROUND(G, c, d, a, b, in[4] + K2,  9);
	ROUND(G, b, c, d, a, in[6] + K2, 13);

	/* Round 3 */
	ROUND(H, a, b, c, d, in[3] + K3,  3);

/* 학습 해설
 * ext4 해시 버전 선택: seed·major/minor·오류 결과
 * 디스크에 기록된 인덱스를 찾으려면 그 디렉터리에 지정된 해시 버전과 seed 규칙으로 다시 계산해야 합니다. 같은 파일 이름에 아무 해시나 적용하면 기존 검색 위치와 맞지 않습니다.
 * __ext4fs_dirhash는 네 기본 seed word를 설정합니다. hinfo->seed가 있고 그중 하나라도 0이 아니면 네 word 전체를 복사합니다. HALF_MD4_UNSIGNED와 TEA_UNSIGNED는 문자열 변환 포인터를 unsigned로 바꾼 뒤 공통 본문으로 fallthrough합니다. half-MD4는 32바이트씩, TEA는 16바이트씩 처리합니다. legacy는 minor=0입니다. SipHash는 암호 키가 있을 때 계산한 64비트의 상위/하위를 major/minor로 나눕니다.
 * seed=[0,0,7,0]이면 세 번째 값만 바꾸는 것이 아니라 네 word 모두 복사합니다. 지원하지 않는 버전은 hinfo의 두 결과를 0으로 쓰고 -EINVAL입니다. SipHash에 키가 없으면 경고 후 -1이며 그 분기에서는 출력 필드를 지우지 않습니다. 오류 결과에서 예전 hinfo 값을 새 해시로 사용하면 안 됩니다.
 */
static int __ext4fs_dirhash(const struct inode *dir, const char *name, int len,
			    struct dx_hash_info *hinfo)
{
	__u32	hash;
	__u32	minor_hash = 0;
	const char	*p;
	int		i;
	__u32		in[8], buf[4];
	void		(*str2hashbuf)(const char *, int, __u32 *, int) =
				str2hashbuf_signed;

	/* Initialize the default seed for the hash checksum functions */
	buf[0] = 0x67452301;
	buf[1] = 0xefcdab89;
	buf[2] = 0x98badcfe;
	buf[3] = 0x10325476;

	/* Check to see if the seed is all zero's */
	if (hinfo->seed) {
		for (i = 0; i < 4; i++) {
			if (hinfo->seed[i]) {
				memcpy(buf, hinfo->seed, sizeof(buf));
				break;
			}
		}
	}

/* 학습 해설
 * ext4 대소문자 접기: 임시 버퍼 수명과 원래 바이트로의 복귀
 * 대소문자를 구별하지 않는 디렉터리는 원래 철자가 달라도 대응하는 이름을 같은 규칙으로 검색해야 합니다. 해시 전 이름을 casefold하되 메모리 부족과 변환 실패의 경로도 따로 처리해야 합니다.
 * CONFIG_UNICODE가 켜진 빌드에서 len이 0이 아니고 CASEFOLDED이며 암호화되지 않았거나 키가 있을 때 임시 PATH_MAX 버퍼를 kzalloc합니다. 할당 실패는 -ENOMEM입니다. utf8_casefold가 음수이면 버퍼를 해제하고 opaque_seq로 가 원래 name,len을 해시합니다. 성공이면 변환된 buff,dlen으로 내부 해시를 호출하고 버퍼를 해제한 뒤 그 결과를 반환합니다. 조건을 만족하지 않거나 Unicode 코드가 빠진 빌드도 원래 이름을 내부 함수에 넘깁니다.
 * 변환용 버퍼를 얻었으나 casefold가 실패했다면 이 wrapper는 그 음수 값을 그대로 반환하지 않고 원래 바이트의 해시 경로로 갑니다. 반면 kzalloc 실패는 즉시 -ENOMEM이라 원래 이름으로 우회하지 않습니다. 내부 해시가 실패한 경우도 성공한 casefold 경로의 버퍼는 해제된 후 오류가 전달됩니다.
 */
int ext4fs_dirhash(const struct inode *dir, const char *name, int len,
		   struct dx_hash_info *hinfo)
{
#if IS_ENABLED(CONFIG_UNICODE)
	const struct unicode_map *um = dir->i_sb->s_encoding;
	int r, dlen;
	unsigned char *buff;
	struct qstr qstr = {.name = name, .len = len };

	if (len && IS_CASEFOLDED(dir) &&
	   (!IS_ENCRYPTED(dir) || fscrypt_has_encryption_key(dir))) {
		buff = kzalloc(sizeof(char) * PATH_MAX, GFP_KERNEL);
		if (!buff)
			return -ENOMEM;

		dlen = utf8_casefold(um, &qstr, buff, PATH_MAX);
		if (dlen < 0) {
			kfree(buff);
			goto opaque_seq;
		}

		r = __ext4fs_dirhash(dir, buff, dlen, hinfo);

		kfree(buff);
		return r;
	}

/* 학습 해설
 * x86 분산 CPUID 기능 탐지: 조회 범위와 레지스터 비트의 연결
 * CPU 기능 비트는 하나의 레지스터에 모두 모여 있지 않습니다. 조회 leaf와 subleaf, 반환 레지스터, 비트 위치를 함께 알아야 하므로 표로 규칙을 저장하고 공통 루프로 해석하면 기능마다 비슷한 분기를 복제하지 않아도 됩니다.
 * cpuid_bits의 각 항목에는 커널 feature 번호, reg, bit, level, sub_leaf가 있습니다. init_scattered_cpuid_features는 feature가 0인 끝 항목 전까지 순회합니다. cpuid_eax(level & 0xffff0000)로 그 영역의 최대 level을 읽고 max가 요청보다 작거나 level|0xffff보다 크면 건너뜁니다. 통과하면 cpuid_count로 EAX·EBX·ECX·EDX 네 결과를 받고 선택한 regs[reg]의 (1<<bit)가 켜졌을 때 set_cpu_cap을 호출합니다.
 * level=7이면 먼저 leaf 0에서 최대값을 읽습니다. 최대값이 6이면 leaf 7은 조회하지 않습니다. level=0x80000007이면 기준은 0x80000000입니다. 표의 FAST_CPPC는 이 leaf의 EDX bit15이므로 그 결과가 0x8000이면 이 기능을 표시합니다. regs 배열의 비트 번호와 커널 feature 번호는 서로 다른 좌표입니다.
 */
void init_scattered_cpuid_features(struct cpuinfo_x86 *c)
{
	u32 max_level;
	u32 regs[4];
	const struct cpuid_bit *cb;

	for (cb = cpuid_bits; cb->feature; cb++) {

		/* Verify that the level is valid */
		max_level = cpuid_eax(cb->level & 0xffff0000);
		if (max_level < cb->level ||
		    max_level > (cb->level | 0xffff))
			continue;

		cpuid_count(cb->level, cb->sub_leaf, &regs[CPUID_EAX],
			    &regs[CPUID_EBX], &regs[CPUID_ECX],
			    &regs[CPUID_EDX]);

		if (regs[cb->reg] & (1 << cb->bit))
			set_cpu_cap(c, cb->feature);
	}
}

/* 학습 해설
 * 자격 증명 준비: memcpy 뒤에도 참조를 따로 얻는 이유
 * 이미 다른 코드에서 읽는 자격 증명 객체를 직접 고치면 검사 중 UID나 그룹 정보가 바뀔 수 있습니다. 수정할 새 객체를 준비한 뒤 공개하는 방식으로 읽는 쪽과 변경하는 쪽의 책임을 나눕니다.
 * prepare_creds는 cred_jar에서 GFP_KERNEL로 객체를 할당하고 실패하면 NULL입니다. 실제 본문은 task->cred를 old로 읽어 struct cred 전체를 복사합니다. new의 non_rcu=0, usage=1로 초기화하고 group_info·user·user_ns의 참조를 얻습니다. CONFIG_KEYS이면 네 key 참조를 얻고 CONFIG_SECURITY이면 복사된 security 포인터를 NULL로 바꿉니다. ucounts 참조나 security_prepare_creds가 실패하면 abort_creds로 정리하고 NULL입니다. 성공은 아직 task에 설치하지 않은 new입니다.
 * memcpy가 old의 group_info 주소를 복사해도 그 그룹 객체의 참조 수는 자동으로 늘지 않습니다. 그래서 get_group_info 등이 필요합니다. prepare 성공 후 호출자가 허용된 변경을 하고 commit하거나, 변경을 포기하면 abort해야 합니다. 이미 commit이 소비한 참조를 다시 abort해서는 안 됩니다.
 */
struct cred *prepare_creds(void)
{
	struct task_struct *task = current;
	const struct cred *old;
	struct cred *new;

	new = kmem_cache_alloc(cred_jar, GFP_KERNEL);
	if (!new)
		return NULL;

	kdebug("prepare_creds() alloc %p", new);

	old = task->cred;
	memcpy(new, old, sizeof(struct cred));

	new->non_rcu = 0;
	atomic_long_set(&new->usage, 1);
	get_group_info(new->group_info);
	get_uid(new->user);
	get_user_ns(new->user_ns);

#ifdef CONFIG_KEYS
	key_get(new->session_keyring);
	key_get(new->process_keyring);
	key_get(new->thread_keyring);
	key_get(new->request_key_auth);

/* 학습 해설
 * 자격 증명 공개: 두 포인터와 두 참조를 함께 바꾸기
 * 프로세스를 대상으로 검사할 때의 real_cred와 현재 작업에 사용하는 cred를 함께 새 자격 증명으로 바꿔야 일반 상태가 일관됩니다. 포인터만 바꾸고 참조 수를 정리하지 않으면 이전 객체가 누수되거나 새 객체가 일찍 해제됩니다.
 * commit_creds는 old=task->real_cred이고 task->cred가 old와 다르면 BUG_ON입니다. new usage가 1 이상인지도 검사합니다. 호출자의 new 참조를 소비하고 get_cred로 주관적 포인터용 참조 하나를 추가합니다. euid·egid·fsuid·fsgid 중 하나가 다르거나 새 capability가 이전 권한의 부분집합이 아니면, mm이 있을 때 dumpability를 suid_dumpable로 바꾸고 pdeath_signal을 0으로 만든 뒤 smp_wmb를 수행합니다. fsuid/fsgid 변경은 key hook을 호출합니다. user 또는 namespace가 바뀌면 새 process count를 올리고 두 포인터를 rcu_assign_pointer로 공개한 뒤 이전 count를 내립니다. uid·euid·suid·fsuid 중 하나라도 바뀌면 UID 알림, gid·egid·sgid·fsgid 중 하나라도 바뀌면 GID 알림을 보냅니다. 마지막으로 old 참조 두 개를 내려놓고 0입니다.
 * 다른 소유자가 없다는 단순 예에서 new usage=1로 들어오면 get_cred 후 2가 되어 두 task 포인터가 소유합니다. old에도 두 task 참조가 있었다면 마지막에 2를 줄입니다. 다른 독자가 가진 참조까지 강제로 제거하는 것은 아닙니다. 성공 뒤 caller가 new를 추가로 put하면 넘겨준 소유 참조를 이중으로 내려놓는 오류입니다.
 */
int commit_creds(struct cred *new)
{
	struct task_struct *task = current;
	const struct cred *old = task->real_cred;

	kdebug("commit_creds(%p{%ld})", new,
	       atomic_long_read(&new->usage));

	BUG_ON(task->cred != old);
	BUG_ON(atomic_long_read(&new->usage) < 1);

	get_cred(new); /* we will require a ref for the subj creds too */

	/* dumpability changes */
	if (!uid_eq(old->euid, new->euid) ||
	    !gid_eq(old->egid, new->egid) ||
	    !uid_eq(old->fsuid, new->fsuid) ||
	    !gid_eq(old->fsgid, new->fsgid) ||
	    !cred_cap_issubset(old, new)) {
		if (task->mm)
			set_dumpable(task->mm, suid_dumpable);
		task->pdeath_signal = 0;
		/*
		 * If a task drops privileges and becomes nondumpable,
		 * the dumpability change must become visible before
		 * the credential change; otherwise, a __ptrace_may_access()
		 * racing with this change may be able to attach to a task it
		 * shouldn't be able to attach to (as if the task had dropped
		 * privileges without becoming nondumpable).
		 * Pairs with a read barrier in __ptrace_may_access().
		 */

/* 학습 해설
 * 임시 자격 증명: override와 revert의 소유권 짝
 * 일부 커널 작업은 잠시 다른 자격으로 권한 검사를 수행한 뒤 원래 상태로 돌아가야 합니다. 프로세스 자체의 객관적 자격까지 영구 변경하면 작업 범위를 넘기므로 cred만 교체하는 별도 경로가 있습니다.
 * override_creds는 current->cred를 old로 보관하고 get_new_cred(new)로 임시 설치에 필요한 참조를 얻습니다. current->cred만 rcu_assign_pointer로 바꾼 뒤 old를 반환합니다. get_cred와 달리 get_new_cred를 써 non_rcu 표시를 지우지 않습니다. revert_creds(old)는 현재 임시 cred를 보관하고 old를 다시 설치한 뒤 임시 cred를 put합니다. real_cred는 이 두 함수에서 바꾸지 않습니다.
 * old=O 상태에서 A로 override한 반환값 O를 보존합니다. 다시 B로 override하면 반환값 A를 보존합니다. 종료는 revert(A)로 B의 설치 참조를 놓고, revert(O)로 A의 설치 참조를 놓는 역순입니다. 원래 old의 참조를 중간에 임의로 put하면 복귀할 객체의 수명 계약이 깨집니다.
 */
const struct cred *override_creds(const struct cred *new)
{
	const struct cred *old = current->cred;

	kdebug("override_creds(%p{%ld})", new,
	       atomic_long_read(&new->usage));

	/*
	 * NOTE! This uses 'get_new_cred()' rather than 'get_cred()'.
	 *
	 * That means that we do not clear the 'non_rcu' flag, since
	 * we are only installing the cred into the thread-synchronous
	 * '->cred' pointer, not the '->real_cred' pointer that is
	 * visible to other threads under RCU.
	 */
	get_new_cred((struct cred *)new);
	rcu_assign_pointer(current->cred, new);

	kdebug("override_creds() = %p{%ld}", old,
	       atomic_long_read(&old->usage));
	return old;
}
EXPORT_SYMBOL(override_creds);

/**
 * revert_creds - Revert a temporary subjective credentials override
 * @old: The credentials to be restored
 *
 * Revert a temporary set of override subjective credentials to an old set,
 * discarding the override set.
 */

/* 학습 해설
 * Capability 부분집합: 같은 namespace와 조상 namespace의 다른 규칙
 * capability 비트가 같은 숫자라고 해도 서로 다른 user namespace에서 의미하는 권한 범위가 같지는 않습니다. 자격 증명 변경의 권한 관계를 확인하려면 비트 집합뿐 아니라 namespace 계층과 소유자도 봐야 합니다.
 * cred_cap_issubset(set,subset)은 namespace가 같으면 subset의 cap_permitted가 set의 cap_permitted에 포함되는지 검사합니다. 다르면 subset_ns에서 init_user_ns 전까지 부모를 따라 올라갑니다. 현재 노드의 부모가 set_ns이고 그 노드 owner가 set->euid와 같으면 true이며 끝까지 없으면 false입니다. commit_creds는 old를 set, new를 subset으로 넘기고 결과가 false인 경우에도 dumpability 변경 조건에 들어갑니다.
 * 같은 namespace에서 old={A,B},new={B}면 포함되고 new={B,C}면 포함되지 않습니다. 다른 namespace에서 P 아래 C 아래 G가 있을 때 set이 P,subset이 G이면 처음 G의 부모 C를 보고 다음 C의 부모 P를 봅니다. 이때 검사하는 owner는 C의 owner입니다. G의 owner만 같다는 이유로 P와의 조건을 통과하지 않습니다.
 */
static bool cred_cap_issubset(const struct cred *set, const struct cred *subset)
{
	const struct user_namespace *set_ns = set->user_ns;
	const struct user_namespace *subset_ns = subset->user_ns;

	/* If the two credentials are in the same user namespace see if
	 * the capabilities of subset are a subset of set.
	 */
	if (set_ns == subset_ns)
		return cap_issubset(subset->cap_permitted, set->cap_permitted);

	/* The credentials are in a different user namespaces
	 * therefore one is a subset of the other only if a set is an
	 * ancestor of subset and set->euid is owner of subset or one
	 * of subsets ancestors.
	 */
	for (;subset_ns != &init_user_ns; subset_ns = subset_ns->parent) {
		if ((set_ns == subset_ns->parent)  &&
		    uid_eq(subset_ns->owner, set->euid))
			return true;
	}

	return false;
}

/**
 * commit_creds - Install new credentials upon the current task
 * @new: The credentials to be assigned
 *
 * Install a new set of credentials to the current task, using RCU to replace
 * the old set.  Both the objective and the subjective credentials pointers are
 * updated.  This function may not be called if the subjective credentials are
 * in an overridden state.
 *
 * This function eats the caller's reference to the new credentials.
 *
 * Always returns 0 thus allowing this function to be tail-called at the end
 * of, say, sys_setgid().
 */

/* 학습 해설
 * 자격 증명 해제: 참조 0 이후에도 RCU를 기다리는 이유
 * 참조 수를 가진 소유자는 없어졌어도 RCU 읽기 구간에서 이전 포인터를 잠시 읽는 독자가 있을 수 있습니다. 참조 0과 메모리를 즉시 재사용해도 되는 시점은 항상 같지 않습니다.
 * __put_cred는 usage가 0인지, current의 cred와 real_cred가 해당 객체가 아닌지 BUG_ON으로 확인합니다. non_rcu가 참이면 put_cred_rcu를 직접 호출하고 그렇지 않으면 call_rcu로 예약합니다. 콜백은 usage가 여전히 0인지 검사하고 아니면 panic입니다. security hook, 네 key 참조, 조건부 group_info, user, 조건부 ucounts, user namespace를 순서대로 정리한 뒤 cred_jar에 객체를 반환합니다.
 * 마지막 put에서 usage가 1→0이 되어도 non_rcu=0이면 callback이 예약되므로 그 시점에 곧바로 slab free가 실행됐다고 가정하지 않습니다. 반대로 non_rcu 경로는 같은 해제 함수를 즉시 호출합니다. 어느 경로든 호출자가 마지막 참조를 반납한 뒤 그 포인터를 다시 읽어도 된다는 뜻은 아닙니다.
 */
void __put_cred(struct cred *cred)
{
	kdebug("__put_cred(%p{%ld})", cred,
	       atomic_long_read(&cred->usage));

	BUG_ON(atomic_long_read(&cred->usage) != 0);
	BUG_ON(cred == current->cred);
	BUG_ON(cred == current->real_cred);

	if (cred->non_rcu)
		put_cred_rcu(&cred->rcu);
	else
		call_rcu(&cred->rcu, put_cred_rcu);
}
EXPORT_SYMBOL(__put_cred);

/*
 * Clean up a task's credentials when it exits
 */
void exit_creds(struct task_struct *tsk)
{
	struct cred *real_cred, *cred;

	kdebug("exit_creds(%u,%p,%p,{%ld})", tsk->pid, tsk->real_cred, tsk->cred,
	       atomic_long_read(&tsk->cred->usage));

/* 학습 해설
 * 다른 task의 자격 증명 읽기: 0을 되살리지 않는 재시도
 * 다른 task가 자격 증명을 교체하는 동안 포인터만 읽고 나중에 참조를 늘리면 이미 소유자가 모두 놓은 객체를 되살리는 경쟁이 생길 수 있습니다. RCU 구간에서 읽고 0이 아닌 경우에만 참조를 늘리는 절차가 필요합니다.
 * get_task_cred는 RCU 읽기 구간을 열고 __task_cred로 객관적 real_cred를 읽습니다. NULL이면 BUG_ON입니다. get_cred_rcu가 실패하면 새로 포인터를 읽으며 반복합니다. get_cred_rcu는 atomic_long_inc_not_zero로 참조를 얻고 성공하면 non_rcu=0으로 만듭니다. 참조 획득 뒤 RCU를 풀고 객체를 반환합니다. 호출자는 사용 후 put_cred할 책임이 있습니다.
 * 처음 읽은 A의 usage가 이미 0이면 inc_not_zero는 A를 1로 살리지 않습니다. 루프가 다시 읽어 교체된 B의 유효한 참조를 얻을 수 있습니다. RCU는 이 시도 동안 이전 객체 메모리 수명을 보호하고, 성공한 참조는 RCU 구간을 나간 뒤에도 반환 객체를 보유하게 합니다. 두 수단의 보호 시간이 다릅니다.
 */
const struct cred *get_task_cred(struct task_struct *task)
{
	const struct cred *cred;

	rcu_read_lock();

	do {
		cred = __task_cred((task));
		BUG_ON(!cred);
	} while (!get_cred_rcu(cred));

	rcu_read_unlock();
	return cred;
}
EXPORT_SYMBOL(get_task_cred);

/*
 * Allocate blank credentials, such that the credentials can be filled in at a
 * later date without risk of ENOMEM.
 */
struct cred *cred_alloc_blank(void)
{
	struct cred *new;

	new = kmem_cache_zalloc(cred_jar, GFP_KERNEL);
	if (!new)

/* 학습 해설
 * exec 자격 준비: effective ID 복사와 keyring 참조 정리
 * 프로그램 교체 때 이전 실행 문맥의 모든 keyring을 그대로 들고 가면 새 프로그램의 자격 준비 규칙과 맞지 않을 수 있습니다. 일반 자격 복사 위에 exec 전용 정리를 더하는 단계가 필요합니다.
 * prepare_exec_creds의 호출자는 cred_guard_mutex를 보유해야 합니다. prepare_creds가 실패하면 그 NULL을 그대로 반환합니다. CONFIG_KEYS에서는 새 복사본의 thread_keyring과 process_keyring 참조를 각각 key_put하고 NULL로 만듭니다. session_keyring은 이 함수에서 지우지 않습니다. 이어 suid와 fsuid를 euid에, sgid와 fsgid를 egid에 맞춥니다. 반환은 아직 commit되지 않은 new입니다.
 * 복사본의 euid=1000, suid=2000, fsuid=3000이면 이 단계 후 suid=fsuid=1000입니다. uid 자체를 이 함수가 1000으로 덮는 것은 아닙니다. process_keyring=NULL은 여기서 새 keyring 객체를 즉시 할당했다는 뜻도 아닙니다.
 */
struct cred *prepare_exec_creds(void)
{
	struct cred *new;

	new = prepare_creds();
	if (!new)
		return new;

#ifdef CONFIG_KEYS
	/* newly exec'd tasks don't get a thread keyring */
	key_put(new->thread_keyring);
	new->thread_keyring = NULL;

	/* inherit the session keyring; new process keyring */
	key_put(new->process_keyring);
	new->process_keyring = NULL;
#endif

	new->suid = new->fsuid = new->euid;
	new->sgid = new->fsgid = new->egid;

	return new;
}

/*
 * Copy credentials for the new process created by fork()
 *
 * We share if we can, but under some circumstances we have to generate a new
 * set.
 *
 * The new process gets the current process's subjective credentials as its
 * objective and subjective credentials
 */

/* 학습 해설
 * fork 자격 복제: 공유 조건과 새 namespace의 실패 정리
 * 자격이 같은 스레드마다 객체를 복제하면 메모리와 참조 관리 비용이 늘지만 thread keyring이나 user namespace가 달라야 할 때는 같은 객체를 그대로 쓸 수 없습니다. 공유 가능한 경우와 분리해야 하는 경우를 조건으로 나눕니다.
 * copy_creds는 요청 key 캐시 설정에서 자식의 cached_requested_key를 NULL로 만듭니다. CLONE_THREAD이고 CONFIG_KEYS에서 기존 thread_keyring이 없으면 get_cred_many(...,2)로 두 자식 포인터용 참조를 얻고 process ucounts를 올려 0입니다. 그 밖에는 prepare_creds를 하며 실패는 -ENOMEM입니다. CLONE_NEWUSER이면 create_user_ns와 set_cred_ucounts를 차례로 실행하고 음수면 new를 put하고 그 오류를 반환합니다.
 * 새 객체 경로에서 기존 thread_keyring은 참조를 놓고 NULL로 만든 뒤 CLONE_THREAD이면 설치 helper를 호출합니다. 스레드가 아니면 process_keyring도 참조를 놓고 NULL입니다. 마지막 p->cred와 p->real_cred는 get_cred(new)로 참조 하나를 더 얻어 같은 객체를 가리키며 새 process ucounts를 올립니다. 준비 시 참조 1과 추가 참조 1이 두 포인터를 담당합니다.
 */
int copy_creds(struct task_struct *p, unsigned long clone_flags)
{
	struct cred *new;
	int ret;

#ifdef CONFIG_KEYS_REQUEST_CACHE
	p->cached_requested_key = NULL;
#endif

	if (
#ifdef CONFIG_KEYS
		!p->cred->thread_keyring &&
#endif
		clone_flags & CLONE_THREAD
	    ) {
		p->real_cred = get_cred_many(p->cred, 2);
		kdebug("share_creds(%p{%ld})",
		       p->cred, atomic_long_read(&p->cred->usage));
		inc_rlimit_ucounts(task_ucounts(p), UCOUNT_RLIMIT_NPROC, 1);
		return 0;
	}

	new = prepare_creds();
	if (!new)
		return -ENOMEM;

/* 학습 해설
 * 커널 작업용 자격: daemon 기준 복사와 NULL 거절
 * 커널 서비스가 다른 작업을 대신할 때 기준이 되는 자격을 명확히 선택해야 합니다. 함수 이름에 kernel이 있다는 이유만으로 언제나 같은 권한을 생성한다고 생각하면 호출 계약을 놓칩니다.
 * prepare_kernel_cred는 daemon이 NULL이면 WARN_ON_ONCE 후 NULL입니다. slab 할당 실패도 NULL입니다. get_task_cred(daemon)으로 기준 자격을 참조한 뒤 구조체를 복사하고 non_rcu=0,usage=1로 설정합니다. user·namespace·group 참조를 얻고 CONFIG_KEYS의 네 keyring/auth 포인터는 NULL, jit_keyring은 thread 기본값으로 둡니다. security 포인터는 보안 설정에서 NULL로 초기화합니다. ucounts 참조와 security_prepare_creds가 성공하면 old를 put하고 new를 반환합니다.
 * ucounts나 보안 준비 실패이면 new와 old를 각각 put한 뒤 NULL입니다. CONFIG_KEYS에서 key 포인터를 NULL로 대입하는 것은 복사본이 그 old key들에 대한 참조를 새로 얻지 않으므로 정리 시 이전 key 참조를 잘못 내려놓지 않게 하는 의미도 있습니다. 반환된 new는 아직 current의 자격으로 설치되지 않았습니다.
 */
struct cred *prepare_kernel_cred(struct task_struct *daemon)
{
	const struct cred *old;
	struct cred *new;

	if (WARN_ON_ONCE(!daemon))
		return NULL;

	new = kmem_cache_alloc(cred_jar, GFP_KERNEL);
	if (!new)
		return NULL;

	kdebug("prepare_kernel_cred() alloc %p", new);

	old = get_task_cred(daemon);

	*new = *old;
	new->non_rcu = 0;
	atomic_long_set(&new->usage, 1);
	get_uid(new->user);
	get_user_ns(new->user_ns);
	get_group_info(new->group_info);

#ifdef CONFIG_KEYS
	new->session_keyring = NULL;
	new->process_keyring = NULL;

/* 학습 해설
 * 파일 접근 자격 비교: ID·그룹 수·배열 순서로 정렬하기
 * 일부 파일 접근 문맥에서 두 자격이 같은 UID/GID/보조 그룹 조건을 갖는지 비교해야 합니다. 정렬 가능한 비교 결과를 얻으려면 무엇을 먼저 비교할지 고정해야 합니다.
 * cred_fscmp는 객체 주소가 같으면 0입니다. 다르면 fsuid, fsgid 순서로 작으면 -1, 크면 1입니다. 이후 group_info 주소가 같으면 0, 한쪽 NULL이면 NULL 쪽이 작습니다. 둘 다 있으면 ngroups 수를 먼저 비교하고 같을 때 gid 배열을 앞에서부터 비교합니다. 끝까지 같으면 0입니다. 결과는 임의적이지만 안정적인 비교 순서이지 권한의 크기 등급이 아닙니다.
 * fsuid와 fsgid가 같고 A 그룹=[100], B 그룹=[1,2]이면 그룹 수 1<2로 A가 먼저라 -1입니다. 첫 그룹 값 100이 1보다 크다는 사실은 이 경우까지 비교하지 않습니다. 둘 다 길이 2라면 처음 다른 gid 값이 순서를 결정합니다.
