int cred_fscmp(const struct cred *a, const struct cred *b)
{
	struct group_info *ga, *gb;
	int g;

	if (a == b)
		return 0;
	if (uid_lt(a->fsuid, b->fsuid))
		return -1;
	if (uid_gt(a->fsuid, b->fsuid))
		return 1;

	if (gid_lt(a->fsgid, b->fsgid))
		return -1;
	if (gid_gt(a->fsgid, b->fsgid))
		return 1;

	ga = a->group_info;
	gb = b->group_info;
	if (ga == gb)
		return 0;
	if (ga == NULL)
		return -1;
	if (gb == NULL)
		return 1;
	if (ga->ngroups < gb->ngroups)

/* 학습 해설
 * 사용량 계정 교체: 새 참조 확보 뒤 이전 것을 놓기
 * UID나 user namespace를 바꾸면 프로세스 수 등의 사용량을 연결할 계정도 맞춰야 합니다. 먼저 이전 계정을 해제하고 새 계정을 구하면 실패 시 유효한 연결을 잃으므로 확보·교체·해제의 순서가 필요합니다.
 * set_cred_ucounts는 old_ucounts의 namespace와 uid가 new의 user_ns·uid와 같으면 바로 0입니다. 원문 주석은 alloc_ucounts의 표 검색이 잠금을 사용하므로 이 빠른 경로가 필요하다고 설명합니다. 다르면 새 계정을 할당/획득하고 실패하면 -EAGAIN입니다. 성공한 뒤 new->ucounts를 바꾸고 이전 참조를 put한 후 0입니다.
 * 기존 계정 A와 새 UID의 계정 B가 다를 때 B 확보 실패이면 new->ucounts는 여전히 A입니다. B를 얻으면 B로 교체한 뒤 A 참조를 놓습니다. 이 helper는 new->uid나 new->user_ns를 직접 바꾸지 않고 이미 수정된 값에 계정 포인터를 맞춥니다.
 */
int set_cred_ucounts(struct cred *new)
{
	struct ucounts *new_ucounts, *old_ucounts = new->ucounts;

	/*
	 * This optimization is needed because alloc_ucounts() uses locks
	 * for table lookups.
	 */
	if (old_ucounts->ns == new->user_ns && uid_eq(old_ucounts->uid, new->uid))
		return 0;

	if (!(new_ucounts = alloc_ucounts(new->user_ns, new->uid)))
		return -EAGAIN;

	new->ucounts = new_ucounts;
	put_ucounts(old_ucounts);

	return 0;
}

/*
 * initialise the credentials stuff
 */
void __init cred_init(void)
{
	/* allocate a slab in which we can store credentials */

/* 학습 해설
 * LSM 자격 설정: 문자열 변환과 부분 변경 후 실패
 * 일반 UID/GID와 LSM 보안 문맥은 서로 다른 검사 요소입니다. 둘을 함께 준비하는 helper라도 오류 반환 시 어디까지 바뀌었는지 알아야 안전하게 취소하거나 다시 준비할 수 있습니다.
 * set_create_files_as는 inode의 uid나 gid가 유효하지 않으면 -EINVAL이고 필드를 바꾸지 않습니다. 유효하면 new의 fsuid와 fsgid에 inode 값을 먼저 복사하고 security_kernel_create_files_as의 결과를 반환합니다. set_security_override는 security_kernel_act_as를 호출해 결과를 전달합니다. from_ctx 변형은 strlen 길이로 security_secctx_to_secid를 호출하며 음수면 바로 반환하고 아니면 얻은 secid로 set_security_override를 호출합니다.
 * LSM의 create-files hook이 오류를 반환해도 앞에서 대입한 fsuid·fsgid는 자동으로 원래 값으로 돌아가지 않습니다. 아직 공개하지 않은 new를 abort하거나 적절히 정리해야 합니다. 문자열→secid 변환 자체가 실패한 경우에는 act_as까지 호출하지 않습니다.
 */
int set_create_files_as(struct cred *new, struct inode *inode)
{
	if (!uid_valid(inode->i_uid) || !gid_valid(inode->i_gid))
		return -EINVAL;
	new->fsuid = inode->i_uid;
	new->fsgid = inode->i_gid;
	return security_kernel_create_files_as(new, inode);
}
EXPORT_SYMBOL(set_create_files_as);

/* 학습 해설
 * 빈 자격 증명과 초기 자격: 0으로 채우기와 root 설정은 다르다
 * 나중에 채울 객체를 미리 확보하는 것과 현재 자격을 복사하는 것은 다른 목적입니다. 또 메모리의 모든 비트를 0으로 만드는 것만으로 필요한 참조와 권한 문맥이 완성되는 것은 아닙니다.
 * cred_alloc_blank는 cred_jar에서 zalloc하고 실패하면 NULL입니다. usage를 1로 만들고 security_cred_alloc_blank를 호출합니다. 보안 준비가 음수면 abort_creds 후 NULL, 아니면 새 객체를 반환합니다. user·group·namespace 참조를 여기서 현재 자격에서 복사하지 않습니다. cred_init은 cred 구조체용 slab cache를 만들며 cache-line 정렬, cache 생성 실패 시 panic, memcg 회계 플래그를 지정합니다. SLAB_ACCOUNT는 CONFIG_MEMCG가 없으면 사용하지 않는 플래그가 됩니다.
 * blank에서 필드가 0이라는 사실을 prepare_creds와 같은 사용 가능한 복사본이라는 뜻으로 읽으면 안 됩니다. 예를 들어 set_cred_ucounts는 기존 ucounts를 바로 역참조하므로 blank 객체에 아무 준비 없이 호출하는 전제가 맞지 않습니다. cache 생성의 SLAB_PANIC도 개별 cred 할당의 모든 실패가 panic이라는 뜻은 아닙니다. alloc 함수들은 NULL을 검사합니다.
 */
struct cred *cred_alloc_blank(void)
{
	struct cred *new;

	new = kmem_cache_zalloc(cred_jar, GFP_KERNEL);
	if (!new)
		return NULL;

	atomic_long_set(&new->usage, 1);
	if (security_cred_alloc_blank(new, GFP_KERNEL_ACCOUNT) < 0)
		goto error;

	return new;

error:
	abort_creds(new);
	return NULL;
}

/**
 * prepare_creds - Prepare a new set of credentials for modification
 *
 * Prepare a new set of task credentials for modification.  A task's creds
 * shouldn't generally be modified directly, therefore this function is used to
 * prepare a new copy, which the caller then modifies and then commits by
 * calling commit_creds().
 *
 * Preparation involves making a copy of the objective creds for modification.
