	struct blk_flush_queue *fq = blk_get_flush_queue(q, ctx);

	if (q->elevator) {
		WARN_ON(rq->tag < 0);
		blk_mq_put_driver_tag(rq);
	}

	/*
	 * After populating an empty queue, kick it to avoid stall.  Read
	 * the comment in flush_end_io().
	 */
	spin_lock_irqsave(&fq->mq_flush_lock, flags);
	fq->flush_data_in_flight--;
	/*
	 * May have been corrupted by rq->rq_next reuse, we need to
	 * re-initialize rq->queuelist before reusing it here.
	 */
	INIT_LIST_HEAD(&rq->queuelist);
	blk_flush_complete_seq(rq, fq, REQ_FSEQ_DATA, error);

/* 학습 해설
 * 순수 flush 요청: 빈 bio를 제출하고 완료를 기다리기
 * 데이터를 새로 쓰지 않고 이미 장치 캐시에 들어간 쓰기를 비휘발성 저장소로 밀어내고 싶을 수 있습니다. 이 경우 데이터 페이지를 억지로 붙이지 않고 빈 bio에 PREFLUSH 의미를 담습니다.
 * blkdev_issue_flush는 스택의 bio를 bdev, vector NULL, 개수0, WRITE|PREFLUSH로 초기화하고 submit_bio_wait 결과를 반환합니다. 연결 helper는 스택 completion을 bi_private에 넣고 완료 callback을 설치하며 REQ_SYNC를 더해 제출한 뒤 blk_wait_io로 기다립니다. 마지막 bio->bi_status를 errno로 변환해 반환합니다.
 * write cache가 없는 장치의 빈 flush는 블록 계층에서 실질적 장치 I/O 없이 성공 완료될 수 있습니다. 따라서 성공했다고 항상 물리적인 FLUSH 명령이 발행됐다고 단정하지 않습니다. 반대로 장치 오류가 전달되면 호출자는 반환된 errno를 처리해야 합니다.
 */
int blkdev_issue_flush(struct block_device *bdev)
{
	struct bio bio;

	bio_init(&bio, bdev, NULL, 0, REQ_OP_WRITE | REQ_PREFLUSH);
	return submit_bio_wait(&bio);
}
EXPORT_SYMBOL(blkdev_issue_flush);

struct blk_flush_queue *blk_alloc_flush_queue(int node, int cmd_size,
					      gfp_t flags)
{
	struct blk_flush_queue *fq;
	int rq_sz = sizeof(struct request);

	fq = kzalloc_node(sizeof(*fq), flags, node);
	if (!fq)
		goto fail;

	spin_lock_init(&fq->mq_flush_lock);

	rq_sz = round_up(rq_sz + cmd_size, cache_line_size());
	fq->flush_rq = kzalloc_node(rq_sz, flags, node);
	if (!fq->flush_rq)
		goto fail_rq;

/* 학습 해설
 * Flush 큐의 수명: 두 번 할당의 실패 정리와 lockdep 분류
 * flush 상태 목록과 재사용 request는 별도 메모리입니다. 두 번째 할당이 실패했을 때 첫 번째를 남겨 두면 누수가 생기므로 부분 초기화의 정리 경로가 필요합니다.
 * blk_alloc_flush_queue는 지정 NUMA node에서 큐를 0으로 할당하고 실패하면 NULL입니다. 잠금을 초기화한 뒤 request 크기+cmd_size를 cache_line_size 배수로 올려 두 번째 메모리를 할당합니다. 실패하면 큐를 kfree하고 NULL입니다. 성공하면 두 flush 목록을 초기화해 반환합니다. blk_free_flush_queue는 NULL이면 아무것도 하지 않고 아니면 request와 큐를 차례로 해제합니다.
 * 예시로 request 기본 크기160, cmd_size24, cache line64라면 합184를192로 올립니다. 이는 설명용 숫자이며 실제 struct request 크기는 빌드에 따라 다릅니다. free 함수는 진행 중 I/O를 기다리거나 목록을 비우지 않으므로 사용이 끝난 수명 계약을 호출자가 보장해야 합니다. cmd_size와 node 및 flags도 유효한 호출 인자를 요구하며 임의의 사용자 입력 크기를 검증하는 파서는 아닙니다.
 */
struct blk_flush_queue *blk_alloc_flush_queue(int node, int cmd_size,
					      gfp_t flags)
{
	struct blk_flush_queue *fq;
	int rq_sz = sizeof(struct request);

	fq = kzalloc_node(sizeof(*fq), flags, node);
	if (!fq)
		goto fail;

	spin_lock_init(&fq->mq_flush_lock);

	rq_sz = round_up(rq_sz + cmd_size, cache_line_size());
	fq->flush_rq = kzalloc_node(rq_sz, flags, node);
	if (!fq->flush_rq)
		goto fail_rq;

	INIT_LIST_HEAD(&fq->flush_queue[0]);
	INIT_LIST_HEAD(&fq->flush_queue[1]);

	return fq;

 fail_rq:
	kfree(fq);
 fail:
	return NULL;

/* 학습 해설
 * Notifier 등록: 우선순위 정렬과 같은 항목의 중복 방지
 * 여러 하위 시스템이 같은 이벤트를 받고 싶을 때 호출 목록을 하드코딩하면 기능을 추가할 때마다 발행자를 수정해야 합니다. callback을 목록에 등록하고 우선순위대로 호출하면 발행자와 수신자를 분리할 수 있습니다.
 * notifier_block은 callback·next·priority를 가집니다. core 등록 함수는 포인터를 가리키는 포인터 nl로 연결 위치를 찾습니다. 같은 block 주소를 만나면 경고와 -EEXIST입니다. 새 priority가 현재보다 크면 그 앞에서 멈춥니다. priority가 같고 unique_priority이면 -EBUSY입니다. 아니면 next로 진행하므로 일반 등록은 같은 우선순위의 기존 항목 뒤에 삽입합니다. n->next를 정하고 rcu_assign_pointer로 연결한 뒤 trace와 0입니다.
 * A=100,B=50인 목록에 C=75를 넣으면 A→C→B입니다. D=75를 일반 등록하면 C 뒤, unique 등록이면 C를 만나 -EBUSY입니다. core 삭제는 같은 주소를 찾아 앞 링크를 n->next로 연결하고 trace 후0이며 끝까지 없으면 -ENOENT입니다. 등록된 priority나 next를 임의 변경하지 않는 정상 목록 계약이 필요합니다.
 */
static int notifier_chain_register(struct notifier_block **nl,
				   struct notifier_block *n,
				   bool unique_priority)
{
	while ((*nl) != NULL) {
		if (unlikely((*nl) == n)) {
			WARN(1, "notifier callback %ps already registered",
			     n->notifier_call);
			return -EEXIST;
		}
		if (n->priority > (*nl)->priority)
			break;
		if (n->priority == (*nl)->priority && unique_priority)
			return -EBUSY;
		nl = &((*nl)->next);
	}
	n->next = *nl;
	rcu_assign_pointer(*nl, n);
	trace_notifier_register((void *)n->notifier_call);
	return 0;
}

static int notifier_chain_unregister(struct notifier_block **nl,
		struct notifier_block *n)
{
	while ((*nl) != NULL) {

/* 학습 해설
 * Notifier 호출: 마지막 반환값과 STOP 비트의 의미
 * 여러 callback의 결과를 합산할지, 한 callback이 후속 호출을 막을지 정해져 있어야 발행자가 결과를 해석할 수 있습니다. notifier는 마지막 반환값과 STOP 비트를 사용하며 일반 errno와 같은 숫자 규칙이 아닙니다.
 * notifier_call_chain은 ret=NOTIFY_DONE에서 시작해 next를 미리 읽고 callback(nb,val,v)을 부릅니다. nr_calls가 있으면 실제 호출 수를 증가시킨 뒤 STOP_MASK가 있으면 중단합니다. 계속하면 다음 노드로 가고 nr_to_call을 줄입니다. 0은 호출 없음, -1은 제한 없이 목록을 돌기 위한 계약입니다. CONFIG_DEBUG_NOTIFIERS에서 함수 포인터가 kernel text가 아니면 경고 후 다음 노드로 건너뛰며 호출 수와 제한을 줄이지 않습니다.
 * A가 OK=1, B가 DONE=0이면 최종 결과는1이 아니라 마지막 B의0입니다. B가 STOP=0x8001이면 B까지 호출하고 멈춥니다. BAD=0x8002와 STOP은 모두 중단 비트가 있지만 BAD의 거부 의미와 STOP의 정상 중단 의미가 다릅니다. 아무 callback도 없으면 DONE=0입니다.
 */
static int notifier_call_chain(struct notifier_block **nl,
			       unsigned long val, void *v,
			       int nr_to_call, int *nr_calls)
{
	int ret = NOTIFY_DONE;
	struct notifier_block *nb, *next_nb;

	nb = rcu_dereference_raw(*nl);

	while (nb && nr_to_call) {
		next_nb = rcu_dereference_raw(nb->next);

#ifdef CONFIG_DEBUG_NOTIFIERS
		if (unlikely(!func_ptr_is_kernel_text(nb->notifier_call))) {
			WARN(1, "Invalid notifier called!");
			nb = next_nb;
			continue;
		}
#endif
		trace_notifier_run((void *)nb->notifier_call);
		ret = nb->notifier_call(nb, val, v);

		if (nr_calls)
			(*nr_calls)++;

		if (ret & NOTIFY_STOP_MASK)

/* 학습 해설
 * Robust notifier 복구: 실패한 항목을 빼고 앞에서 다시 호출
 * 이벤트 처리 중 일부 수신자가 상태를 바꾼 뒤 후속 수신자가 중단을 요청하면 앞의 수신자에게 되돌림 이벤트를 알려야 할 수 있습니다. 어떤 항목까지 복구할지 호출 수로 기록합니다.
 * robust core는 up 이벤트를 제한 없이 호출하며 nr를 셉니다. 결과에 STOP_MASK가 있으면 동일 목록의 처음부터 down 이벤트를 최대 nr-1개에 호출합니다. 마지막에 반환하는 값은 원래 up 결과입니다. 중단을 낸 callback 자체는 nr에 포함되므로1을 빼 복구 대상에서 제외합니다. 복구는 역순이 아니라 같은 순서이고 down도 STOP을 반환하면 더 일찍 멈출 수 있습니다.
 * A,B가 진행하고 C가 STOP이면 up 호출 수3입니다. 복구는 down(A),down(B)이며 C와 뒤 D는 제외합니다. C가 BAD가 아니라 정상 STOP이어도 이 구현의 조건은 STOP_MASK이므로 복구 경로에 들어갑니다. 첫 A가 중단하면 nr-1=0이라 down 호출은 없습니다.
 */
static int notifier_call_chain_robust(struct notifier_block **nl,
				     unsigned long val_up, unsigned long val_down,
				     void *v)
{
	int ret, nr = 0;

	ret = notifier_call_chain(nl, val_up, v, -1, &nr);
	if (ret & NOTIFY_STOP_MASK)
		notifier_call_chain(nl, val_down, v, nr-1, NULL);

	return ret;
}

/*
 *	Atomic notifier chain routines.  Registration and unregistration
 *	use a spinlock, and call_chain is synchronized by RCU (no locks).
 */

/**
 *	atomic_notifier_chain_register - Add notifier to an atomic notifier chain
 *	@nh: Pointer to head of the atomic notifier chain
 *	@n: New entry in notifier chain
 *
 *	Adds a notifier to an atomic notifier chain.
 *
 *	Returns 0 on success, %-EEXIST on error.
 */

/* 학습 해설
 * Atomic notifier: writer 잠금과 RCU 독자의 수명
 * 인터럽트나 원자 문맥에서 이벤트를 전달할 때 callback 실행 중 잠드는 잠금을 잡을 수 없습니다. 목록 변경은 짧은 spinlock으로 보호하고 실행은 RCU 읽기로 보호하는 구조를 사용합니다.
 * atomic 등록과 unique 등록은 spin_lock_irqsave 아래 core 등록에 각각 false/true를 전달합니다. 해제는 같은 잠금 아래 core 삭제를 하고 unlock 뒤 synchronize_rcu를 호출한 다음 ret을 반환합니다. 이벤트 호출은 rcu_read_lock 안에서 제한 없는 core 순회를 수행합니다. empty 확인은 !rcu_access_pointer(head)이며 목록을 영구 고정하는 참조를 얻지 않습니다.
 * 해제 대상이 없어 core가 -ENOENT라도 이 wrapper는 synchronize_rcu를 거친 뒤 반환합니다. 삭제로 새 순회가 객체에 도달하지 않게 하고, 이미 객체를 읽고 실행하던 RCU 구간이 끝나기를 기다리는 단계가 별도입니다. callback은 block하면 안 되며 callback 안에서 이 unregister를 호출해서는 안 됩니다.
 */
int atomic_notifier_chain_unregister(struct atomic_notifier_head *nh,
		struct notifier_block *n)
{
	unsigned long flags;
	int ret;

	spin_lock_irqsave(&nh->lock, flags);
	ret = notifier_chain_unregister(&nh->head, n);
	spin_unlock_irqrestore(&nh->lock, flags);
	synchronize_rcu();
	return ret;
}
EXPORT_SYMBOL_GPL(atomic_notifier_chain_unregister);

/**
 *	atomic_notifier_call_chain - Call functions in an atomic notifier chain
 *	@nh: Pointer to head of the atomic notifier chain
 *	@val: Value passed unmodified to notifier function
 *	@v: Pointer passed unmodified to notifier function
 *
 *	Calls each function in a notifier chain in turn.  The functions
 *	run in an atomic context, so they must not block.
 *	This routine uses RCU to synchronize with changes to the chain.
 *
 *	If the return value of the notifier can be and'ed
 *	with %NOTIFY_STOP_MASK then atomic_notifier_call_chain()
 *	will return immediately, with the return value of
 *	the notifier function which halted execution.
 *	Otherwise the return value is the return value
 *	of the last notifier function called.
 */

/* 학습 해설
 * Blocking notifier: 읽기·쓰기 잠금과 부팅 중 예외
 * callback이 잠들 수 있는 이벤트는 원자 notifier와 다른 보호가 필요합니다. 실행 중 목록 변경을 막되 여러 실행자가 동시에 목록을 읽는 것은 허용하는 rwsem으로 역할을 나눕니다.
 * 일반 상태의 등록·unique 등록은 내부 wrapper에서 down_write 후 core 등록, up_write입니다. 삭제도 write 잠금입니다. SYSTEM_BOOTING에는 task 전환이 아직 준비되지 않은 상황을 위해 잠금 호출 없이 core로 직접 갑니다. 일반 호출과 robust 호출은 head를 먼저 관찰하고 비어 있지 않으면 down_read 후 각각 core를 실행하고 up_read합니다. 비어 있으면 DONE입니다.
 * 잠금 전 head가 있더라도 잠금을 얻기 전에 삭제될 수 있습니다. core가 잠금 안에서 head를 다시 읽으므로 빈 목록으로 처리할 수 있습니다. 반대로 처음 관찰이 비어 있으면 곧바로 DONE일 수 있으므로 동시에 등록된 새 callback까지 반드시 이번 이벤트를 받는다는 보장은 아닙니다.
 */
int blocking_notifier_call_chain(struct blocking_notifier_head *nh,
		unsigned long val, void *v)
{
	int ret = NOTIFY_DONE;

	/*
	 * We check the head outside the lock, but if this access is
	 * racy then it does not matter what the result of the test
	 * is, we re-check the list after having taken the lock anyway:
	 */
	if (rcu_access_pointer(nh->head)) {
		down_read(&nh->rwsem);
		ret = notifier_call_chain(&nh->head, val, v, -1, NULL);
		up_read(&nh->rwsem);
	}
	return ret;
}
EXPORT_SYMBOL_GPL(blocking_notifier_call_chain);

/*
 *	Raw notifier chain routines.  There is no protection;
 *	the caller must provide it.  Use at your own risk!
 */

/**
 *	raw_notifier_chain_register - Add notifier to a raw notifier chain
 *	@nh: Pointer to head of the raw notifier chain
 *	@n: New entry in notifier chain
 *
 *	Adds a notifier to a raw notifier chain.
 *	All locking must be provided by the caller.
 *
 *	Returns 0 on success, %-EEXIST on error.
 */

/* 학습 해설
 * Raw notifier: 보호를 호출자에게 맡기는 네 wrapper
 * 일부 하위 시스템은 이미 자신만의 잠금과 수명 규칙을 갖고 있습니다. 그 상황에 추가 잠금 모델을 강제하지 않고 공통 목록·호출 알고리즘만 쓰도록 raw 인터페이스가 있습니다.
 * raw 등록은 core 등록에 unique=false, 삭제는 core 삭제, 일반 호출은 core call_chain에 nr_to_call=-1과 nr_calls=NULL을 전달합니다. robust 호출은 up/down 두 순회의 core를 직접 호출합니다. 네 wrapper 모두 자체 spinlock·rwsem·RCU 읽기 구간을 만들지 않습니다.
 * 외부 mutex가 목록 등록·삭제와 두 번의 robust 순회 전체를 보호한다면 호출자가 요구된 불변 목록 계약을 구성할 수 있습니다. 하지만 아무 보호 없이 다른 CPU가 삭제·해제하면 raw 함수가 대신 기다려 주지 않습니다. callback이 잠들 수 있는지도 실제 외부 문맥에 따라 결정해야 합니다.
 */
int raw_notifier_call_chain(struct raw_notifier_head *nh,
		unsigned long val, void *v)
{
	return notifier_call_chain(&nh->head, val, v, -1, NULL);
}
EXPORT_SYMBOL_GPL(raw_notifier_call_chain);

/*
 *	SRCU notifier chain routines.    Registration and unregistration
 *	use a mutex, and call_chain is synchronized by SRCU (no locks).
 */

/**
 *	srcu_notifier_chain_register - Add notifier to an SRCU notifier chain
 *	@nh: Pointer to head of the SRCU notifier chain
 *	@n: New entry in notifier chain
 *
 *	Adds a notifier to an SRCU notifier chain.
 *	Must be called in process context.
 *
 *	Returns 0 on success, %-EEXIST on error.
 */
int srcu_notifier_chain_register(struct srcu_notifier_head *nh,
		struct notifier_block *n)
{
	int ret;

/* 학습 해설
 * SRCU notifier: 잠드는 독자와 제거 후 대기
 * callback이 잠들어야 하지만 이벤트 호출은 잦고 등록 해제는 드문 경우, 읽기 쓰기 semaphore 대신 sleepable RCU로 실행 구간을 보호할 수 있습니다. 삭제 후 독자를 기다리는 비용과 호출 경로의 비용을 다르게 배치합니다.
 * SRCU 등록·삭제는 일반 상태에서 mutex로 core 변경을 보호합니다. 삭제는 mutex를 푼 뒤 synchronize_srcu를 호출하고 ret을 반환합니다. 부팅 중에는 두 함수 모두 core로 직접 가므로 삭제의 이 대기도 건너뜁니다. 호출은 srcu_read_lock이 돌려준 idx를 보관하고 core 순회 뒤 같은 idx로 srcu_read_unlock합니다. callback은 process 문맥에서 block할 수 있습니다.
 * srcu_init_notifier_head는 mutex를 초기화하고 init_srcu_struct가 음수면 BUG를 내며 head=NULL로 둡니다. void 함수라 초기화 실패를 errno로 반환하지 않습니다. 동적으로 초기화한 head를 해제할 때는 SRCU cleanup이 먼저 필요하다는 주석이 있습니다. 여러 호출자가 동시에 독자가 될 수 있어 callback 내부의 공유 상태까지 직렬화되는 것은 아닙니다.
 */
int srcu_notifier_chain_unregister(struct srcu_notifier_head *nh,
		struct notifier_block *n)
{
	int ret;

	/*
	 * This code gets used during boot-up, when task switching is
	 * not yet working and interrupts must remain disabled.  At
	 * such times we must not call mutex_lock().
	 */
	if (unlikely(system_state == SYSTEM_BOOTING))
		return notifier_chain_unregister(&nh->head, n);

	mutex_lock(&nh->mutex);
	ret = notifier_chain_unregister(&nh->head, n);
	mutex_unlock(&nh->mutex);
	synchronize_srcu(&nh->srcu);
	return ret;
}
EXPORT_SYMBOL_GPL(srcu_notifier_chain_unregister);

/**
 *	srcu_notifier_call_chain - Call functions in an SRCU notifier chain
 *	@nh: Pointer to head of the SRCU notifier chain
 *	@val: Value passed unmodified to notifier function
 *	@v: Pointer passed unmodified to notifier function
 *
 *	Calls each function in a notifier chain in turn.  The functions
 *	run in a process context, so they are allowed to block.
 *
 *	If the return value of the notifier can be and'ed
 *	with %NOTIFY_STOP_MASK then srcu_notifier_call_chain()
 *	will return immediately, with the return value of
 *	the notifier function which halted execution.
 *	Otherwise the return value is the return value
 *	of the last notifier function called.
 */

/* 학습 해설
 * Die notifier: 스택 이벤트 데이터와 원자 callback
 * 예외 관련 정보에 관심 있는 기능을 고정 호출 목록 대신 이벤트 체인으로 연결할 수 있습니다. 다만 전달하는 레지스터 포인터와 스택 데이터의 수명은 이벤트 실행 범위와 맞아야 합니다.
 * notify_die는 die_args에 regs,str,err,trapnr,signr을 채웁니다. RCU가 watching 상태가 아니면 RCU_LOCKDEP_WARN을 기록하도록 하고, die_chain의 atomic notifier를 val과 args 주소로 호출해 결과를 반환합니다. 이 경고를 독립적인 error return이나 자동 RCU 초기화라고 볼 수는 없습니다. register_die_notifier와 unregister_die_notifier는 각각 atomic 등록·해제 wrapper에 위임합니다.
 * args 자체는 notify_die의 스택 객체이므로 callback이 그 주소를 저장한 채 함수 반환 뒤 비동기 작업에서 읽으면 안 됩니다. 필요한 값을 이후에 쓰려면 각 필드가 가리키는 대상의 수명까지 고려해 안전하게 복사·참조해야 합니다. atomic callback 규칙상 잠드는 동작도 허용되지 않습니다.
 */
int notrace notify_die(enum die_val val, const char *str,
	       struct pt_regs *regs, long err, int trap, int sig)
{
	struct die_args args = {
		.regs	= regs,
		.str	= str,
		.err	= err,
		.trapnr	= trap,
		.signr	= sig,

	};
	RCU_LOCKDEP_WARN(!rcu_is_watching(),
			   "notify_die called but RCU thinks we're quiescent");
	return atomic_notifier_call_chain(&die_chain, val, &args);
}
NOKPROBE_SYMBOL(notify_die);

int register_die_notifier(struct notifier_block *nb)
{
	return atomic_notifier_chain_register(&die_chain, nb);
}
EXPORT_SYMBOL_GPL(register_die_notifier);

int unregister_die_notifier(struct notifier_block *nb)
{
	return atomic_notifier_chain_unregister(&die_chain, nb);

/* 학습 해설
 * 장치 클래스 반복자: 다음으로 이동하면 이전 참조는 끝난다
 * 장치 목록을 순회하는 동안 장치가 제거될 수 있으므로 잠깐 읽은 포인터만 믿고 사용하면 안 됩니다. 반복자가 현재 노드 참조를 보유하면 callback이 장치를 사용하는 동안 메모리 수명을 지킬 수 있습니다.
 * class_dev_iter_init은 class_to_subsys로 내부 객체 참조를 얻고 start의 klist 노드 또는 NULL로 반복자를 초기화하며 type과 sp를 저장합니다. next는 klist_next로 진행하고 type이 없거나 dev->type 포인터가 같은 장치만 반환합니다. 반환 장치는 다음 이동 또는 exit까지 참조됩니다. exit는 klist 반복자를 끝내고 내부 sp 참조를 내려놓습니다. 중간에 순회를 중단해도 exit가 필요합니다.
 * A→B→C에서 정상적으로 A를 start로 잡고 klist 참조를 얻었다면 첫 next는 A 다음 B로 진행합니다. start=NULL이면 처음부터입니다. A를 반환받은 뒤 next로 이동하면서 A의 iterator 참조는 내려갈 수 있으므로 A를 나중에 보관하려면 별도 device 참조가 필요합니다. type 검사는 타입 이름 문자열 비교가 아니라 동일한 device_type 포인터인지의 비교입니다.
 */
struct device *class_dev_iter_next(struct class_dev_iter *iter)
{
	struct klist_node *knode;
	struct device *dev;

	while (1) {
		knode = klist_next(&iter->ki);
		if (!knode)
			return NULL;
		dev = klist_class_to_dev(knode);
		if (!iter->type || iter->type == dev->type)
			return dev;
	}
}
EXPORT_SYMBOL_GPL(class_dev_iter_next);

/**
 * class_dev_iter_exit - finish iteration
 * @iter: class iterator to finish
 *
 * Finish an iteration.  Always call this function after iteration is
 * complete whether the iteration ran till the end or not.
 */
void class_dev_iter_exit(struct class_dev_iter *iter)
{
	klist_iter_exit(&iter->ki);

/* 학습 해설
 * 장치 클래스 검색: match의 비0과 추가 get_device
 * 순회 중 발견한 장치를 반복자가 끝난 뒤에도 사용하려면 검색 결과에 독립적인 참조를 넘겨야 합니다. 단순 순회 callback과 검색 callback의 반환 규약도 다릅니다.
 * class_find_device는 class 또는 내부 sp가 없으면 NULL이고, 초기화 안 된 class에는 경고를 합니다. 반복 중 match(dev,data)가 비0이면 get_device(dev)로 참조를 더하고 멈춥니다. iterator exit와 처음 얻은 sp put을 수행한 후 dev를 반환합니다. 사용자는 찾은 장치를 다 쓴 뒤 put_device해야 합니다. 찾지 못하면 next가 NULL인 상태로 반환합니다.
 * class_for_each_device는 같은 검사와 정리를 하되 callback fn이 비0이면 멈추고 그 값을 그대로 반환합니다. match에서 -1을 오류 뜻으로 반환해도 find는 비0이라 일치로 처리합니다. fn에서 양수7을 반환하면 for_each는 중단 후7을 반환합니다. 반환값이 모두 통일된 errno 규칙이라고 생각하면 안 됩니다.
 */
struct device *class_find_device(const struct class *class, const struct device *start,
				 const void *data, device_match_t match)
{
	struct subsys_private *sp = class_to_subsys(class);
	struct class_dev_iter iter;
	struct device *dev;

	if (!class)
		return NULL;
	if (!sp) {
		WARN(1, "%s called for class '%s' before it was initialized",
		     __func__, class->name);
		return NULL;
	}

	class_dev_iter_init(&iter, class, start, NULL);
	while ((dev = class_dev_iter_next(&iter))) {
		if (match(dev, data)) {
			get_device(dev);
			break;
		}
	}
	class_dev_iter_exit(&iter);
	subsys_put(sp);

	return dev;

/* 학습 해설
 * 클래스 sysfs 속성: show·store callback과 -EIO 기본값
 * sysfs가 공통 kobject와 attribute로 읽기·쓰기를 요청해도 실제 장치 클래스는 자신만의 속성 함수를 가지고 있습니다. 공통 객체에서 포함 구조체를 찾아 올바른 callback으로 연결하는 어댑터가 필요합니다.
 * class_attr_show는 container_of 기반 to_class_attr로 class_attribute를 얻고 kobject에서 subsys_private를 찾습니다. ret은 -EIO로 시작하며 show가 있으면 class·attribute·buf를 전달한 결과로 바꿉니다. store도 같은 구조로 buf와 count를 추가 전달합니다. class_sysfs_ops가 두 wrapper를 연결하고 class_ktype은 이 ops, release, child_ns_type을 연결합니다. child_ns_type은 해당 class의 ns_type을 반환합니다.
 * show callback이 없으면 빈 문자열 길이0이 아니라 -EIO입니다. store callback이3을 반환하면 wrapper도3을 반환하며 count 전부를 썼다고 자동으로 바꾸지 않습니다. show_class_attr_string은 포함 class_attribute_string을 찾아 sysfs_emit으로 문자열과 개행을 출력합니다.
 */
static ssize_t class_attr_show(struct kobject *kobj, struct attribute *attr,
			       char *buf)
{
	struct class_attribute *class_attr = to_class_attr(attr);
	struct subsys_private *cp = to_subsys_private(kobj);
	ssize_t ret = -EIO;

	if (class_attr->show)
		ret = class_attr->show(cp->class, class_attr, buf);
	return ret;
}

static ssize_t class_attr_store(struct kobject *kobj, struct attribute *attr,
				const char *buf, size_t count)
{
	struct class_attribute *class_attr = to_class_attr(attr);
	struct subsys_private *cp = to_subsys_private(kobj);
	ssize_t ret = -EIO;

	if (class_attr->store)
		ret = class_attr->store(cp->class, class_attr, buf, count);
	return ret;
}

static void class_release(struct kobject *kobj)
{

/* 학습 해설
 * 클래스 등록: namespace 쌍 검사와 단계별 실패 정리
 * 외부에 class 이름을 공개하기 전에 내부 장치 목록·잠금·sysfs 연결을 준비해야 합니다. 중간 단계가 실패했을 때 등록되지 않은 내부 메모리와 진단용 잠금 키가 남지 않도록 정리 경로도 필요합니다.
 * class_register는 ns_type만 있거나 namespace callback만 있으면 -EINVAL입니다. 두 값이 모두 있거나 모두 없으면 진행합니다. subsys_private를 kzalloc해 실패하면 -ENOMEM이고, 장치 klist·interface 목록·glue_dirs kset·동적 lockdep key와 mutex를 초기화합니다. 이름을 설정하고 class_kset·class_ktype·class 포인터를 연결한 뒤 kset_register와 class_groups 생성 순서로 공개합니다.
 * 이름 설정이나 kset 등록 실패는 err_out으로 가 lockdep key를 해제하고 cp를 kfree합니다. group 생성 실패는 먼저 kobject_del과 이름의 kfree_const를 수행한 뒤 같은 err_out으로 갑니다. 성공은0입니다. 실패 종류마다 실제 정리 호출이 다르므로 모든 경로에서 무조건 같은 kset_unregister를 호출한다고 써서는 안 됩니다.
 */
int class_register(const struct class *cls)
{
	struct subsys_private *cp;
	struct lock_class_key *key;
	int error;

	pr_debug("device class '%s': registering\n", cls->name);

	if (cls->ns_type && !cls->namespace) {
		pr_err("%s: class '%s' does not have namespace\n",
		       __func__, cls->name);
		return -EINVAL;
	}
	if (!cls->ns_type && cls->namespace) {
		pr_err("%s: class '%s' does not have ns_type\n",
		       __func__, cls->name);
		return -EINVAL;
	}

	cp = kzalloc(sizeof(*cp), GFP_KERNEL);
	if (!cp)
		return -ENOMEM;
	klist_init(&cp->klist_devices, klist_class_dev_get, klist_class_dev_put);
	INIT_LIST_HEAD(&cp->interfaces);
	kset_init(&cp->glue_dirs);
	key = &cp->lock_key;

/* 학습 해설
 * 클래스 생성·해제: ERR_PTR와 최종 release의 역할
 * 동적으로 만든 class를 등록 목록에서 빼는 시점과 마지막 참조가 사라져 메모리를 해제하는 시점은 다를 수 있습니다. 생성용 메모리와 내부 등록 객체도 서로 다른 할당입니다.
 * class_create는 struct class를 0으로 할당하고 name 포인터와 class_create_release callback을 설정한 뒤 class_register를 호출합니다. 실패는 cls를 kfree하고 ERR_PTR(retval)입니다. 성공은 class 포인터입니다. class_destroy는 ERR_PTR 또는 NULL을 무시하고 그 외에는 class_unregister를 호출합니다. unregister는 내부 참조를 얻어 group 제거·kset_unregister·subsys_put 순서로 정리합니다.
 * class_release는 내부 kobject의 최종 release에서 class_release callback이 있으면 호출하고 없으면 debug 메시지를 출력합니다. 이후 내부 lockdep key와 cp를 해제합니다. class_create가 설치한 callback은 외부 cls를 kfree합니다. 따라서 class_destroy가 단순히 cls를 직접 kfree하는 구현은 아닙니다.
 */
struct class *class_create(const char *name)
{
	struct class *cls;
	int retval;

	cls = kzalloc(sizeof(*cls), GFP_KERNEL);
	if (!cls) {
		retval = -ENOMEM;
		goto error;
	}

	cls->name = name;
	cls->class_release = class_create_release;

	retval = class_register(cls);
	if (retval)
		goto error;

	return cls;

error:
	kfree(cls);
	return ERR_PTR(retval);
}
EXPORT_SYMBOL_GPL(class_create);

/* 학습 해설
 * 클래스 인터페이스: 기존 장치 알림과 두 참조 반납
 * 장치가 생기기 전에만 callback을 등록할 수 있다면 이미 존재하는 장치를 놓칩니다. interface 등록 때 기존 장치도 순회해 알리고, interface가 살아 있는 동안 class 내부 객체를 참조해 수명을 유지합니다.
 * class_interface_register는 인자나 class가 없으면 -ENODEV, 내부 class 조회 실패면 -EINVAL입니다. 얻은 sp 참조는 등록 기간 동안 보유합니다. sp mutex 아래 interface를 목록 뒤에 넣고 add_dev가 있으면 현재 장치를 반복해 호출합니다. 반복자를 정리하고 mutex를 푼 뒤0입니다. 헤더상 add_dev는 int 반환이지만 이 등록 함수는 결과를 검사하지 않습니다.
 * unregister는 class를 읽고 없으면 반환하며 내부 sp를 다시 얻습니다. mutex 아래 interface 노드를 지우고 remove_dev가 있으면 현재 장치를 순회해 호출합니다. 반복자 정리·unlock 뒤 sp를 두 번 put합니다. 하나는 이번 조회분, 하나는 등록 기간 소유분입니다. add_dev 하나가 음수를 반환해도 이 등록 함수는 자동 롤백하거나 그 오류를 반환하지 않습니다.
 */
int class_interface_register(struct class_interface *class_intf)
{
	struct subsys_private *sp;
	const struct class *parent;
	struct class_dev_iter iter;
	struct device *dev;

	if (!class_intf || !class_intf->class)
		return -ENODEV;

	parent = class_intf->class;
	sp = class_to_subsys(parent);
	if (!sp)
		return -EINVAL;

	/*
	 * Reference in sp is now incremented and will be dropped when
	 * the interface is removed in the call to class_interface_unregister()
	 */

	mutex_lock(&sp->mutex);
	list_add_tail(&class_intf->node, &sp->interfaces);
	if (class_intf->add_dev) {
		class_dev_iter_init(&iter, parent, NULL, NULL);
		while ((dev = class_dev_iter_next(&iter)))
			class_intf->add_dev(dev);

/* 학습 해설
 * 클래스 호환 링크: 두 번째 생성 실패를 되돌리기
 * 장치 분류 방식이 바뀌어도 기존 사용자 프로그램이 예전 sysfs 경로를 찾을 수 있게 임시 호환 링크를 제공할 수 있습니다. 링크 둘을 만들다가 하나만 남으면 기대한 구조와 달라지므로 실패를 되돌립니다.
 * class_compat_register는 작은 wrapper를 kmalloc하고 class_kset 아래 이름 있는 kobject를 만듭니다. 실패하면 wrapper를 정리하고 NULL입니다. create_link는 먼저 호환 class에서 dev 이름으로 dev kobject에 링크합니다. 실패하면 즉시 오류입니다. 선택적 device_link가 있으면 dev 아래 device라는 이름으로 그 대상에 링크하며 실패 시 첫 링크를 제거합니다. 첫 링크만 필요하고 성공했으면0입니다.
 * 첫 링크 성공, 선택 링크 실패라면 반환은 두 번째 오류이고 첫 링크는 제거됩니다. remove_link는 선택 대상이 있으면 device 링크부터 제거한 뒤 호환 class의 dev 이름 링크를 제거합니다. compat_unregister는 kobject_put 후 wrapper를 kfree하며 자체 NULL 검사는 없습니다.
 */
int class_compat_create_link(struct class_compat *cls, struct device *dev,
			     struct device *device_link)
{
	int error;

	error = sysfs_create_link(cls->kobj, &dev->kobj, dev_name(dev));
	if (error)
		return error;

	/*
	 * Optionally add a "device" link (typically to the parent), as a
	 * class device would have one and we want to provide as much
	 * backwards compatibility as possible.
	 */
	if (device_link) {
		error = sysfs_create_link(&dev->kobj, &device_link->kobj,
					  "device");
		if (error)
			sysfs_remove_link(cls->kobj, dev_name(dev));
	}

	return error;
}
EXPORT_SYMBOL_GPL(class_compat_create_link);

/**
 * class_compat_remove_link - remove a compatibility class device link to
 *			      a bus device
 * @cls: the compatibility class
 * @dev: the target bus device
 * @device_link: an optional device to which a "device" link was previously
 * 		 created
 */

/* 학습 해설
 * 클래스 등록 조회: 순간 상태와 보유 참조는 다르다
 * 등록 여부를 확인하는 질문과 해당 객체가 앞으로도 살아 있도록 붙잡는 것은 다른 작업입니다. boolean만 저장하고 나중에 포인터를 사용하면 사이에 등록 해제가 일어날 수 있습니다.
 * class_is_registered는 class_to_subsys로 내부 객체를 찾아 있으면 true로 표시하고 얻었던 sp 참조를 즉시 put합니다. 없으면 false입니다. 반환 순간에는 보유 참조를 호출자에게 넘기지 않습니다. class_to_subsys는 class 또는 전역 class_kset이 없으면 NULL이고, 목록 잠금 아래 등록 항목의 class 포인터가 같은지 찾은 뒤 subsys_get한 결과를 반환합니다.
 * 현재 true를 받았더라도 다음 줄 전에 다른 경로가 unregister할 수 있으므로 true를 장기 사용 허가증처럼 쓰면 안 됩니다. 클래스 전체의 초기화 classes_init은 class라는 kset을 생성하며 실패는 -ENOMEM, 성공은0입니다. 이 전역 kset이 sysfs의 /sys/class를 위한 기반입니다.
 */
bool class_is_registered(const struct class *class)
{
	struct subsys_private *sp = class_to_subsys(class);
	bool is_initialized = false;

	if (sp) {
		is_initialized = true;
		subsys_put(sp);
	}
	return is_initialized;
}
EXPORT_SYMBOL_GPL(class_is_registered);

int __init classes_init(void)
{
	class_kset = kset_create_and_add("class", NULL, NULL);
	if (!class_kset)
		return -ENOMEM;
	return 0;
}

/* 학습 해설
 * Devm 정리 동작 등록: 실패 시 or_reset이 즉시 실행되는 이유
 * 드라이버 초기화에서 자원을 얻은 뒤 각 오류 분기에 같은 해제 코드를 반복하면 빠뜨리기 쉽습니다. 장치의 관리 자원 목록에 정리 함수를 등록하면 표준 자원 반환 경로에서 호출할 수 있습니다. 하지만 등록 자체의 메모리 할당도 실패할 수 있습니다.
 * __devm_add_action은 action_devres 크기의 관리 메모리를 GFP_KERNEL과 NUMA_NO_NODE로 할당하며 실패하면 -ENOMEM입니다. 성공하면 data와 action 포인터를 저장하고 devres_add로 목록에 추가한 뒤0입니다. devres_add는 devres_lock을 IRQ 상태 저장과 함께 잡아 목록에 연결합니다. 실제 정리 wrapper devm_action_release는 저장한 action(data)를 호출합니다. 등록 성공 시 곧바로 action을 실행하지 않습니다.
 * 이미 확보한 자원 R의 해제 함수 free_R를 일반 add_action으로 등록하다 실패했다면 R 정리는 호출자가 해야 합니다. devm_add_action_or_reset은 내부 add가 비0이면 그 자리에서 action(data)를 실행한 후 원래 오류를 반환합니다. 성공하면 실행하지 않고 나중 정리 목록에 남습니다. 매크로의 #action은 진단용 이름 문자열을 만드는 용도입니다.
 */
int __devm_add_action(struct device *dev, void (*action)(void *), void *data, const char *name)
{
	struct action_devres *devres;

	devres = __devres_alloc_node(devm_action_release, sizeof(struct action_devres),
				     GFP_KERNEL, NUMA_NO_NODE, name);
	if (!devres)
		return -ENOMEM;

	devres->data = data;
	devres->action = action;

	devres_add(dev, devres);
	return 0;
}
EXPORT_SYMBOL_GPL(__devm_add_action);

/**
 * devm_remove_action() - removes previously added custom action
 * @dev: Device that owns the action
 * @action: Function implementing the action
 * @data: Pointer to data passed to @action implementation
 *
 * Removes instance of @action previously added by devm_add_action().
 * Both action and data should match one of the existing entries.
 */

/* 학습 해설
 * Devm remove와 release: 등록 취소와 실제 정리의 차이
 * 장치에서 자원 소유권을 다른 곳으로 넘길 때는 자동 해제 등록만 취소하고 싶을 수 있습니다. 반대로 더 일찍 자원을 반환하고 싶을 때는 지금 정리 함수까지 실행해야 합니다. 두 동작을 구별하지 않으면 누수나 이중 해제가 생깁니다.
 * devm_remove_action과 release_action은 action,data 쌍으로 검색 조건을 만듭니다. match는 함수 포인터와 data 포인터 모두 같은지 검사합니다. remove는 devres_destroy를 호출해 항목을 제거하고 관리 메모리만 해제합니다. release는 devres_release를 호출해 항목 제거 후 devm_action_release로 action(data)를 실행하고 관리 메모리를 해제합니다. 둘 다 찾지 못한 오류는 WARN_ON으로 표시하며 void 반환입니다.
 * 같은 함수에 data=A와 data=B가 등록되어 있으면 data=A 요청은 B와 일치하지 않습니다. 동일한 쌍이 여러 번 있다면 find_dr는 목록 뒤에서 검색하므로 가장 최근 일치 항목 하나가 대상입니다. remove 후 자원 A가 자동 해제됐다고 가정하면 안 되며 release 후 같은 항목이 나중 장치 정리에서 다시 실행되는 것도 아닙니다.
 */
void devm_release_action(struct device *dev, void (*action)(void *), void *data)
{
	struct action_devres devres = {
		.data = data,
		.action = action,
	};

	WARN_ON(devres_release(dev, devm_action_release, devm_action_match,
			       &devres));

}
EXPORT_SYMBOL_GPL(devm_release_action);

/*
 * Managed kmalloc/kfree
 */
static void devm_kmalloc_release(struct device *dev, void *res)
{
	/* noop */
}

static int devm_kmalloc_match(struct device *dev, void *res, void *data)
{
	return res == data;
}

/* 학습 해설
 * Devres 할당: 크기 넘침·정렬·0 초기화의 서로 다른 역할
 * 사용자 데이터 앞에는 목록과 해제 함수 같은 관리 헤더가 필요합니다. 헤더 크기와 데이터 크기를 더한 값이 정수 범위를 넘어 작아지면 실제로 필요한 것보다 작은 메모리를 할당할 수 있어 덧셈 검사부터 해야 합니다.
 * check_dr_size는 sizeof(struct devres)+size를 check_add_overflow로 검사하고 넘치면 false입니다. 정상 크기는 kmalloc_size_roundup으로 할당 버킷 크기에 맞춥니다. alloc_dr는 총 크기로 지정 node에 할당하고 실패면 NULL입니다. __GFP_ZERO가 없을 때만 data 앞까지 memset해 헤더를0으로 만듭니다. 목록 head를 초기화하고 release를 저장합니다. 공개 __devres_alloc_node는 항상 __GFP_ZERO를 더해 호출하고 진단 이름·요청 크기를 기록한 뒤 data 주소를 반환합니다.
 * 설명용8비트 크기 값에서 헤더32+데이터240=272를 검사 없이 저장하면16이 됩니다. 실제 커널은 size_t 범위로 검사하며 이런 작아진 크기로 진행하지 않습니다. struct의 data[]는 ARCH_DMA_MINALIGN 정렬을 요구해 일부 아키텍처의 DMA 정렬 요구에 맞춥니다. 정렬은 크기 넘침 검사나 자동 장치 등록을 대신하지 않습니다.
 */
void *__devres_alloc_node(dr_release_t release, size_t size, gfp_t gfp, int nid,
			  const char *name)
{
	struct devres *dr;

	dr = alloc_dr(release, size, gfp | __GFP_ZERO, nid);
	if (unlikely(!dr))
		return NULL;
	set_node_dbginfo(&dr->node, name, size);
	return dr->data;
}
EXPORT_SYMBOL_GPL(__devres_alloc_node);

/**
 * devres_for_each_res - Resource iterator
 * @dev: Device to iterate resource from
 * @release: Look for resources associated with this release function
 * @match: Match function (optional)
 * @match_data: Data for the match function
 * @fn: Function to be called for each matched resource.
 * @data: Data for @fn, the 3rd parameter of @fn
 *
 * Call @fn for each devres of @dev which is associated with @release
 * and for which @match returns 1.
 *
 * RETURNS:
 * 	void
 */

/* 학습 해설
 * Devres get: 검색과 추가를 하나의 잠금 구간으로 묶기
 * 자원이 없으면 새로 넣는 작업을 검색과 추가 두 단계로 따로 하면 다른 CPU도 같은 결론을 내려 중복 항목을 넣을 수 있습니다. 하나의 잠금 구간 안에서 존재 여부를 결정하고 추가해야 합니다.
 * devres_get은 새 관리 객체의 release 함수를 검색 조건으로 삼습니다. IRQ 상태 저장과 함께 devres_lock을 잡고 find_dr를 호출합니다. 기존 항목이 없으면 add_dr로 새 항목을 붙이고 new_res를 NULL로 만듭니다. 있으면 기존 항목을 선택합니다. 잠금을 푼 뒤 devres_free(new_res)를 호출해 쓰지 않은 새 할당만 해제하고 선택된 data를 반환합니다. find_dr는 뒤에서부터 release와 선택적 match를 검사합니다.
 * A와 B가 같은 조건의 자원을 준비했다면 먼저 잠금 안에서 추가한 A가 남고 B는 그 기존 data를 받아 자기 새 관리 할당을 해제할 수 있습니다. 따라서 호출 뒤에도 입력 new_res가 항상 자기 소유로 살아 있다고 가정하면 안 됩니다. match가 NULL이면 release가 같은 최신 항목이 대상입니다.
 */
void *devres_get(struct device *dev, void *new_res,
		 dr_match_t match, void *match_data)
{
	struct devres *new_dr = container_of(new_res, struct devres, data);
	struct devres *dr;
	unsigned long flags;

	spin_lock_irqsave(&dev->devres_lock, flags);
	dr = find_dr(dev, new_dr->node.release, match, match_data);
	if (!dr) {
		add_dr(dev, &new_dr->node);
		dr = new_dr;
		new_res = NULL;
	}
	spin_unlock_irqrestore(&dev->devres_lock, flags);
	devres_free(new_res);

	return dr->data;
}
EXPORT_SYMBOL_GPL(devres_get);

/**
 * devres_remove - Find a device resource and remove it
 * @dev: Device to find resource from
 * @release: Look for resources associated with this release function
 * @match: Match function (optional)
 * @match_data: Data for the match function
 *
 * Find the latest devres of @dev associated with @release and for
 * which @match returns 1.  If @match is NULL, it's considered to
 * match all.  If found, the resource is removed atomically and
 * returned.
 *
 * RETURNS:
 * Pointer to removed devres on success, NULL if not found.
 */

/* 학습 해설
 * Devres 순회 callback: safe_reverse가 잠금을 풀어 주지는 않는다
 * 관리 자원들을 검사할 때 목록이 변하는 것을 막아야 하지만, callback 실행 문맥이 어떤지도 함께 알아야 합니다. 반복 매크로에 safe라는 이름이 있어도 어떤 동작이든 허용된다는 뜻은 아닙니다.
 * devres_for_each_res는 fn이 NULL이면 바로 반환합니다. 그 외에는 devres_lock을 IRQ 상태 저장과 함께 잡고 뒤에서부터 safe_reverse로 순회합니다. release 함수가 다르면 건너뛰고 match가 있으며0이면 건너뜁니다. 일치하면 fn(dev,data,사용자data)을 잠금 안에서 호출합니다. 마지막에 unlock합니다. fn은 void여서 반환값으로 순회를 중단하는 인터페이스가 아닙니다.
 * A,B,C 순으로 등록된 정상 자원은 조건이 모두 맞으면 C,B,A 순으로 callback이 호출됩니다. fn에서 같은 devres_lock을 얻는 devres_add/remove를 재호출하면 자기 잠금과 충돌할 수 있습니다. 잠드는 작업도 이 spinlock 보유 문맥에 맞지 않습니다.
 */
void devres_for_each_res(struct device *dev, dr_release_t release,
			dr_match_t match, void *match_data,
			void (*fn)(struct device *, void *, void *),
			void *data)
{
	struct devres_node *node;
	struct devres_node *tmp;
	unsigned long flags;

	if (!fn)
		return;

	spin_lock_irqsave(&dev->devres_lock, flags);
	list_for_each_entry_safe_reverse(node, tmp,
			&dev->devres_head, entry) {
		struct devres *dr = container_of(node, struct devres, node);

		if (node->release != release)
			continue;
		if (match && !match(dev, dr->data, match_data))
			continue;
		fn(dev, dr->data, data);
	}
	spin_unlock_irqrestore(&dev->devres_lock, flags);
}
EXPORT_SYMBOL_GPL(devres_for_each_res);

/* 학습 해설
 * Devres 그룹 경계: close와 remove는 자원 해제가 아니다
 * 복잡한 초기화의 한 단계에서 얻은 자원들만 실패 시 되돌리고 싶다면 목록에 시작과 끝 경계를 둘 수 있습니다. 그룹은 별도 목록에 자원을 복사하는 대신 같은 자원 목록에 표식을 넣습니다.
 * devres_open_group은 그룹 객체를 할당해 open/close 두 노드의 식별용 release 함수를 정하고 각각 빈 목록으로 초기화합니다. 진단 이름은 grp<와 grp>이고 크기는0, color=0입니다. id가 NULL이면 그룹 주소를 id로 쓰고 아니면 전달 id를 씁니다. 잠금 아래 open 노드만 추가해 id를 반환합니다. close는 find_group으로 찾아 close 노드를 추가하며 없으면 경고입니다.
 * find_group은 뒤에서 open 표식을 찾습니다. id가 주어지면 주소가 같은 id를, NULL이면 close 노드가 아직 목록에 없는 최신 열린 그룹을 선택합니다. G를 열고 A,B를 추가해 닫으면 G의 경계 안에 A,B가 놓입니다. close는 A,B를 해제하지 않습니다. remove_group은 두 표식을 떼고 그룹 객체만 해제하므로 A,B는 장치 관리 자원으로 남습니다.
 */
void *devres_open_group(struct device *dev, void *id, gfp_t gfp)
{
	struct devres_group *grp;
	unsigned long flags;

	grp = kmalloc(sizeof(*grp), gfp);
	if (unlikely(!grp))
		return NULL;

	grp->node[0].release = &group_open_release;
	grp->node[1].release = &group_close_release;
	INIT_LIST_HEAD(&grp->node[0].entry);
	INIT_LIST_HEAD(&grp->node[1].entry);
	set_node_dbginfo(&grp->node[0], "grp<", 0);
	set_node_dbginfo(&grp->node[1], "grp>", 0);
	grp->id = grp;
	if (id)
		grp->id = id;
	grp->color = 0;

	spin_lock_irqsave(&dev->devres_lock, flags);
	add_dr(dev, &grp->node[0]);
	spin_unlock_irqrestore(&dev->devres_lock, flags);
	return grp->id;
}
EXPORT_SYMBOL_GPL(devres_open_group);

/* 학습 해설
 * Devres 그룹 해제: 두 번 순회하며 포함 관계를 판정하기
 * 선택한 범위 안에 일반 자원뿐 아니라 중첩 그룹의 시작·끝 표식도 있습니다. 범위에 완전히 포함된 그룹만 제거하려면 표식 하나만 보고 판단하지 말고 두 경계의 포함 여부를 확인해야 합니다.
 * release_group은 잠금 아래 그룹을 찾고 범위를 open 표식부터 닫힌 그룹의 close 다음까지, 아직 열렸으면 목록 끝까지로 정합니다. remove_nodes 첫 순회는 일반 자원을 todo에 옮겨 개수를 세고 그룹 표식의 color를0으로 만듭니다. 두 번째 순회는 표식마다 color를 올리며 닫는 표식이 아직 없는 열린 그룹은 한 번 더 올립니다. color가2인 그룹만 open을 todo로 옮기고 close를 제거합니다. 정상 color 범위를 벗어나면 BUG_ON입니다.
 * 닫힌 중첩 그룹의 open과 close가 둘 다 범위에 있으면 color가1→2가 되어 그룹을 제거할 수 있습니다. 하나만 있으면1이라 완전히 포함된 것으로 처리하지 않습니다. 열린 그룹은 open 하나가 범위에 있으면 추가1로2입니다. 함수는 잠금을 풀고 release_nodes를 실행하며 반환 개수는 표식이 아닌 일반 자원 수입니다.
 */
int devres_release_group(struct device *dev, void *id)
{
	struct devres_group *grp;
	unsigned long flags;
	LIST_HEAD(todo);
	int cnt = 0;

	spin_lock_irqsave(&dev->devres_lock, flags);

	grp = find_group(dev, id);
	if (grp) {
		struct list_head *first = &grp->node[0].entry;
		struct list_head *end = &dev->devres_head;

		if (!list_empty(&grp->node[1].entry))
			end = grp->node[1].entry.next;

		cnt = remove_nodes(dev, first, end, &todo);
		spin_unlock_irqrestore(&dev->devres_lock, flags);

		release_nodes(dev, &todo);
	} else {
		WARN_ON(1);
		spin_unlock_irqrestore(&dev->devres_lock, flags);
	}
